import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> nums = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nums.add(sc.nextInt());
        }

        List<Integer> picked = nums.stream()
                .filter(x -> x >= 5)
                .map(x -> x * 2)
                .collect(Collectors.toList());

        System.out.println("够大又翻倍之后：" + picked);
        System.out.println("一共挑出 " + picked.stream().count() + " 件");
        System.out.println("加起来是 " + picked.stream().mapToInt(x -> x).sum());
    }
}

